const body = $json.body || $json;

return [
  {
    json: {
      studentId: String(body.studentId),
      major: String(body.major),
      desiredHours: Number(body.desiredHours),
      pattern: String(body.pattern)
    }
  }
];

// 1. جلب بيانات الطالب المدخلة من نود الإدخال المباشر
const studentInput = $('Student Input').first().json;
const studentId = String(studentInput.studentId).trim();
const major = String(studentInput.major).trim();

const finishedIds = new Set();
const allCourses = [];

// 2. المرور على جميع العناصر القادمة من نود الـ Merge وتوزيعها بدقة
for (const item of items) {
  const data = item.json;

  // إذا كان العنصر يحتوي على StudentID، فهو بالتأكيد من جدول المواد المنجزة (Finished Courses)
  if (data.StudentID !== undefined && data.StudentID !== null) {
    if (String(data.StudentID).trim() === studentId) {
      finishedIds.add(String(data.CourseID).trim());
    }
  } 
  // إذا كان العنصر يحتوي على التخصص وليس فيه StudentID، فهو من جدول المواد الكلي (All Courses)
  else if (data.CourseID && data.Major) {
    allCourses.push(data);
  }
}

// 3. فلترة المواد المتبقية بناءً على التخصص، المواد المنجزة، والمتطلب السابق
const remaining = allCourses.filter(course => {
  const courseId = String(course.CourseID).trim();
  const courseMajor = String(course.Major).trim();

  // شرط 1: يجب أن تكون المادة تابعة لتخصص الطالب
  if (courseMajor !== major) {
    return false;
  }

  // شرط 2: إذا كان الطالب قد أنهى المادة سابقاً، يتم استبعادها
  if (finishedIds.has(courseId)) {
    return false;
  }

  // شرط 3: التحقق من المتطلب السابق (Prerequisite)
  const prereq = String(course.PrerequisiteID || "").trim();

  // إذا لم يكن هناك متطلب سابق، المادة متاحة للتسجيل
  if (prereq === "" || prereq.toLowerCase() === "none" || prereq === "-") {
    return true;
  }

  // إذا كان هناك متطلب، يجب أن يكون الطالب قد أنجزه (موجود في finishedIds)
  return finishedIds.has(prereq);
});

// 4. إعادة النتائج بالصيغة المتوافقة مع n8n
return remaining.map(course => ({
  json: course
}));

const desiredHours = Number(
  $('Student Input').first().json.desiredHours
);

const selectedPattern =
  $('Student Input').first().json.pattern;

// ==================== إعدادات الفلترة للكورسات المخلّصة ====================
// انتبه هنا: غير هذه المسميات لتطابق تماماً الأسماء الموجودة بالشيت عندك
const STATUS_FIELD_NAME = "Status"; // اسم العمود اللي بحدد حالة المادة (مثلاً Status أو Type أو Passed)
const COMPLETED_VALUE = "Completed"; // القيمة اللي بتدل إن المادة مخلصة (مثلاً Completed أو Passed أو نعم)
// =========================================================================

// 1. تصفية الكورسات: استثناء المواد المخلّصة وبناءً على الأيام المحددة
let courses = items
  .map(item => item.json)
  .filter(course => {

    // منع الكورسات التي اجتازها الطالب من الدخول في الجدول الجديد
    if (course[STATUS_FIELD_NAME] === COMPLETED_VALUE) {
      return false;
    }

    // الفلترة بناءً على نمط الأيام المختار
    if (
      selectedPattern === "Sunday-Tuesday-Thursday" &&
      course.Days !== "Sunday, Tuesday, Thursday"
    ) {
      return false;
    }

    if (
      selectedPattern === "Monday-Wednesday" &&
      course.Days !== "Monday, Wednesday"
    ) {
      return false;
    }

    return true;
  });

// 2. خلط الكورسات المتبقية (المتاحة للتسجيل فقط) عشوائياً
for (let i = courses.length - 1; i > 0; i--) {
  const j = Math.floor(Math.random() * (i + 1));
  [courses[i], courses[j]] = [courses[j], courses[i]];
}

const targetCourses = desiredHours / 3;

// دالة تحويل الوقت إلى دقائق
function toMinutes(time) {
  const [h, m] = String(time)
    .split(":")
    .map(Number);
  return h * 60 + m;
}

// دالة فحص التعارض
function hasConflict(course1, course2) {
  const start1 = toMinutes(course1.StartTime);
  const end1 = toMinutes(course1.EndTime);
  const start2 = toMinutes(course2.StartTime);
  const end2 = toMinutes(course2.EndTime);

  return start1 < end2 && end1 > start2;
}

let bestSchedule = [];

// 3. خوارزمية البحث الذكي عن جدول بدون تعارض
function findBestSchedule(index, currentSchedule) {
  if (currentSchedule.length === targetCourses) {
    bestSchedule = [...currentSchedule];
    return true; 
  }

  if (index >= courses.length) {
    if (currentSchedule.length > bestSchedule.length) {
      bestSchedule = [...currentSchedule];
    }
    return false;
  }

  const currentCourse = courses[index];
  let conflict = false;

  for (const selected of currentSchedule) {
    if (hasConflict(currentCourse, selected)) {
      conflict = true;
      break;
    }
  }

  if (!conflict) {
    currentSchedule.push(currentCourse);
    const foundPerfect = findBestSchedule(index + 1, currentSchedule);
    if (foundPerfect) return true;
    currentSchedule.pop(); 
  }

  return findBestSchedule(index + 1, currentSchedule);
}

// تشغيل الخوارزمية
findBestSchedule(0, []);

// 4. المخرجات النهائية لـ n8n بنفس المسميات الأصلية
return [
  {
    json: {
      totalHours: bestSchedule.length * 3,
      schedule: bestSchedule
    }
  }
];
